import{_ as a,o as s,c as n,a4 as r}from"./chunks/framework.BRzJ4ijD.js";const u=JSON.parse('{"title":"Paxos / Multi-Paxos","description":"","frontmatter":{},"headers":[],"relativePath":"distributed/consensus/paxos.md","filePath":"distributed/consensus/paxos.md","lastUpdated":1788475713000}'),o={name:"distributed/consensus/paxos.md"};function t(i,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="paxos-multi-paxos" tabindex="-1">Paxos / Multi-Paxos <a class="header-anchor" href="#paxos-multi-paxos" aria-label="Permalink to &quot;Paxos / Multi-Paxos&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p><strong>Paxos</strong> (Lamport 1989/1998) 是分布式共识的数学基础——让 N=2f+1 节点在异步网络 + crash-recovery 假设下, 对某 proposed value decision 一致。算法分两阶段: <strong>Prepare/Promise (Phase 1)</strong> 让 proposer 拿到 majority quorum 对 proposal number <code>n</code> 的&quot;承诺&quot;; <strong>Accept/Accepted (Phase 2)</strong> 把 chosen value 投给 quorum 通过。两 quorum 必 overlap 保证后续 proposer 不能 reverse 已 accept 的 value。<strong>Multi-Paxos</strong> 用 stable leader 跳过每 entry 的 Phase 1 把它降成 1-RPC commit, 这是 Google Chubby/Megastore/Spanner 的内核算法。本章梳理算法证明, 工程细节 (proposal number 持久化、log fsync、leader lease), typical bugs 以及跟 Raft 的关系。</p><hr><h2 id="一、consensus-形式化" tabindex="-1">一、Consensus 形式化 <a class="header-anchor" href="#一、consensus-形式化" aria-label="Permalink to &quot;一、Consensus 形式化&quot;">​</a></h2><h3 id="safety-永远满足的三-invariant" tabindex="-1">Safety (永远满足的三 invariant) <a class="header-anchor" href="#safety-永远满足的三-invariant" aria-label="Permalink to &quot;Safety (永远满足的三 invariant)&quot;">​</a></h3><ol><li><strong>Agreement (Consistency)</strong>: 不同 process 不能 decide 不同 value.</li><li><strong>Validity (Non-triviality)</strong>: decision 必须曾被 propose——不能凭空 invent。</li><li><strong>Integrity</strong>: 每 process 至多 decide 一次 (no flip)。</li></ol><h3 id="liveness" tabindex="-1">Liveness <a class="header-anchor" href="#liveness" aria-label="Permalink to &quot;Liveness&quot;">​</a></h3><p><strong>Termination</strong>: 在不违 partial-synchrony 假设下 (≥N−f 节点 eventual recover, 消息 eventual deliver) eventually所有 correct process decide。</p><p><strong>FLP 1995</strong> 已证: 纯 async 网络 + 1 node 可能 crash → deterministic consensus 不可解终止. Paxos 用 eventual partial-synchrony 弱假设 + random backoff 绕开 FLP。</p><h3 id="quorum-2f-1-怎么来的" tabindex="-1">Quorum 2f+1 怎么来的 <a class="header-anchor" href="#quorum-2f-1-怎么来的" aria-label="Permalink to &quot;Quorum 2f+1 怎么来的&quot;">​</a></h3><p>设 N=2f+1 节点, 容忍 f crashes. Quorum size = f+1 (majority). 任意两 majority <strong>必</strong> overlap ( 因 (f+1)+(f+1) = 2f+2 &gt; N )。 已 accepted 的 value 通过 overlap 节点传播给下一 proposer——Paxos 安全性核心。</p><hr><h2 id="二、basic-paxos-算法" tabindex="-1">二、Basic Paxos 算法 <a class="header-anchor" href="#二、basic-paxos-算法" aria-label="Permalink to &quot;二、Basic Paxos 算法&quot;">​</a></h2><h3 id="角色" tabindex="-1">角色 <a class="header-anchor" href="#角色" aria-label="Permalink to &quot;角色&quot;">​</a></h3><ul><li><strong>Proposer</strong>: 提出 proposal (n, v), n 是单调增 proposal number。</li><li><strong>Acceptor</strong>: 投票, 保持 (promised_n, accepted_n, accepted_v) per instance。</li><li><strong>Learner</strong>: 收 quorum ACCEPTED -&gt; decide, 通知 clients。</li></ul><p>工程实现: 三 role 同 process, 每个节点同时充当。</p><h3 id="phase-1-prepare-promise" tabindex="-1">Phase 1: Prepare / Promise <a class="header-anchor" href="#phase-1-prepare-promise" aria-label="Permalink to &quot;Phase 1: Prepare / Promise&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proposer P:</span></span>
<span class="line"><span>  n = bump_and_persist_proposal_number()</span></span>
<span class="line"><span>  send PREPARE(n) to a majority of acceptors</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Acceptor A:</span></span>
<span class="line"><span>  if n &gt; promised_n:</span></span>
<span class="line"><span>    promised_n = n        // fsync to WAL</span></span>
<span class="line"><span>    reply PROMISE(n, accepted_n, accepted_v)    // (null if never accepted)</span></span>
<span class="line"><span>  else:</span></span>
<span class="line"><span>    reply REJECT(n)</span></span></code></pre></div><p>Acceptor 承诺不再 accept 比 n 低的 proposal; 同时曝光自己之前 accept 过的 (n&#39;, v&#39;) (if any)。</p><h3 id="phase-2-accept-accepted" tabindex="-1">Phase 2: Accept / Accepted <a class="header-anchor" href="#phase-2-accept-accepted" aria-label="Permalink to &quot;Phase 2: Accept / Accepted&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Proposer P:</span></span>
<span class="line"><span> wait majority PROMISE.</span></span>
<span class="line"><span> let (n_max, v_max) = max accepted_n across replies (or none)</span></span>
<span class="line"><span> if v_max exists:  v = v_max      // 强制采用先前 quorum accepted 的 value</span></span>
<span class="line"><span> else:             v = my_originally_proposed_value</span></span>
<span class="line"><span> send ACCEPT(n, v) to majority of acceptors</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Acceptor A:</span></span>
<span class="line"><span>  if n &gt;= promised_n:</span></span>
<span class="line"><span>    accepted_n = n</span></span>
<span class="line"><span>    accepted_v = v          // fsync to WAL</span></span>
<span class="line"><span>    reply ACCEPTED(n, v) to learners</span></span>
<span class="line"><span>  else:</span></span>
<span class="line"><span>    reply REJECT</span></span></code></pre></div><h3 id="learner" tabindex="-1">Learner <a class="header-anchor" href="#learner" aria-label="Permalink to &quot;Learner&quot;">​</a></h3><p>收集 majority ACCEPTED → decide value → broadcast。</p><h3 id="agreement-证明" tabindex="-1">Agreement 证明 <a class="header-anchor" href="#agreement-证明" aria-label="Permalink to &quot;Agreement 证明&quot;">​</a></h3><p>设两个 different values vA, vB 通过不同 quorum QA, QB (大小 N−f) chosen. Let acceptance instance:</p><p>vA 通过 (nA, vA) 被 QA accept; vB 通过 (nB, vB) 被 QB accept. 不妨 nA &lt; nB. QA 与 QB 大小均为 ≥f+1, 总和 2f+2 &gt; 2f+1 = N → 至少一个 acceptor ∈ QA ∩ QB. 设其为 A. 那当 vB 的 proposer 跑 Phase 1 时, 拿到 majority PROMISE 必含 A 的 PROMISE with accepted_n=nA, accepted_v=vA. vB 的 proposer 在 Phase 2 必须用 v_max中 ≥ vA. ⇒ vB = vA. ✓</p><h3 id="validity-证明" tabindex="-1">Validity 证明 <a class="header-anchor" href="#validity-证明" aria-label="Permalink to &quot;Validity 证明&quot;">​</a></h3><p>任 accepted value v 来自 Proposer&#39;s choice: Phase 2 &quot;若没看到 prior accepted, v=originally proposed; 否则 v=prior accepted value&quot;，递归到达一定来自某 initially proposed value, 不能凭空织造. ✓</p><hr><h2 id="三、multi-paxos" tabindex="-1">三、Multi-Paxos <a class="header-anchor" href="#三、multi-paxos" aria-label="Permalink to &quot;三、Multi-Paxos&quot;">​</a></h2><h3 id="为什么要-stable-leader" tabindex="-1">为什么要 stable leader <a class="header-anchor" href="#为什么要-stable-leader" aria-label="Permalink to &quot;为什么要 stable leader&quot;">​</a></h3><p>Basic Paxos for single value 需要 2 个 RPC round trip per decide. 与 commit 后还要返回 client 又一轮 → 客户端单个 cmd 三个 RTT, 高延迟。</p><p>Multi-Paxos 优化:</p><ol><li>Proposer 跑一普遍 Phase 1 在 leadership begin, 获得承诺 majority acceptors <strong>不再 accept proposal from anyone else</strong>。</li><li>同 leader 任期内, 每 log entry 只跑 Phase 2 ACCEPT, 单 RTT。</li></ol><p>工程上 leader 任期 = lease (e.g., 60s), lease 内 leader 独享 Phase 1 guarantee; lease 过期需 renew。</p><h3 id="log-replication" tabindex="-1">Log Replication <a class="header-anchor" href="#log-replication" aria-label="Permalink to &quot;Log Replication&quot;">​</a></h3><p>State machine model: 一系列 commands c1, c2, ... 多 instance Paxos 每 instance 对应一个 log entry, 各 instance 独立 decide。</p><p>leader 工作流 (稳态):</p><ol><li>client 发 cmd → leader append to log at entry i.</li><li>leader 并行 send ACCEPT(i, n, v) to followers.</li><li>等待 majority ACCEPTED → commit entry i → reply to client.</li><li>leader 串行 apply committed commands to state machine (FIFO order)。</li></ol><p>Pipelining: 在 commit i 时可 RUNNING PERPARE DONE accept for i+1, i+2 同时—— leader WAL 持久化 提速.</p><hr><h2 id="四、工程细节" tabindex="-1">四、工程细节 <a class="header-anchor" href="#四、工程细节" aria-label="Permalink to &quot;四、工程细节&quot;">​</a></h2><h3 id="proposal-number" tabindex="-1">Proposal Number <a class="header-anchor" href="#proposal-number" aria-label="Permalink to &quot;Proposal Number&quot;">​</a></h3><p>每个 proposer 维护 (round, node_id) tuple 作为 proposal_n, lex-sort 保证全序:</p><ul><li>round 单调增整数; 持久化 disk 保 crash-recovery 后 round ≥ restarted value。</li><li>不持久化 → 重启 round 回退 → while active leader 已 accept 的 entry resettings 不做. round==m monarch 落 trike 协调 化.</li></ul><p><strong>Bug</strong>: Google Chubby 用 proposer_id + monotonic counter, fsync 至少每 lease (30s) — 实测 crash 后未 recovered round 发现 validity disgust 姓 lock drop 处理 加 cluded fsync on round_need++ 持 train gap.</p><h3 id="disk-fsync-顺序" tabindex="-1">Disk fsync 顺序 <a class="header-anchor" href="#disk-fsync-顺序" aria-label="Permalink to &quot;Disk fsync 顺序&quot;">​</a></h3><p>每个 acceptor 必先 fsync log, 后 reply ack。 顺序错可丢 safety:</p><ul><li>Acceptor A 落地后, proposer 收 majority ACK → commit → reply client. 如果 A 没 fsync, client 收 success ack 后 A crash → A 重启不认 entry。 client 错认为 commit◈fine promised BA sending Ash. 本质 commit wait-顺序。</li><li><strong>写 ordering</strong>: <code>write WAL -&gt; fsync -&gt; reply ACCEPTED/PROMISE</code></li></ul><p><code>fsync</code> 在 Linux 机械盘 ~10ms, NVMe ~few µs, 即使 NVMe 也 boud。</p><h3 id="lease-leader" tabindex="-1">Lease Leader <a class="header-anchor" href="#lease-leader" aria-label="Permalink to &quot;Lease Leader&quot;">​</a></h3><p>Leader lease 保证 leader 在 lease 期内<strong>不被挑战</strong> —— 避免 Phase 1 重做。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lease_grant (t_start, t_end)</span></span>
<span class="line"><span>n (round, leader_id) stable</span></span>
<span class="line"><span>on lease not expired: skip Phase 1, ACCEPT-only per entry</span></span>
<span class="line"><span>on expiry: leader renew (Phase 1) or new leader elect</span></span></code></pre></div><p><strong>时钟误差处理</strong>: lease expiry time + clock-skew grace period +=2s buffer 是保险。 Chubby 是接口 lease (60s) 与 client (12s default) 同步 over lease gossip 假 同 NTP ≤20s. 单层 lease 长 (lease 1s) + clock skew 100ms synch time 会 be safe if skew-Trim Leader 处理.</p><h3 id="membership-change" tabindex="-1">Membership Change <a class="header-anchor" href="#membership-change" aria-label="Permalink to &quot;Membership Change&quot;">​</a></h3><p>工程里用 <strong>joint consensus</strong>: 集群 config C→C&#39; 转换走 entry 包含 simultaneously <strong>C+ C&#39;</strong>, 各 phase quorum = <code>majority(C) ∩ majority(C&#39;)</code> 联合, 保永远 run 在 multiple quorum. 下一 phase 完全 C&#39; (commit 持续 Quorum only C&#39;bene). Raft 同样 aCPU 单 retry 节点变化是 Wi-Di.</p><h3 id="read-path" tabindex="-1">Read Path <a class="header-anchor" href="#read-path" aria-label="Permalink to &quot;Read Path&quot;">​</a></h3><p>Linearizable read <strong>不</strong> Paxos decision (只是读 statemachine) — 但是 leader 必须 prove 仍是 leader 不会 stale:</p><ol><li><strong>Lease-held read</strong>: leader lease 内能回复不需要 quorum read. 风险 lease timeout+clock skew 同 daemon leader 起按 回 飞成功的 lelapse replace more Leaders, race store over stle.</li><li><strong>Quorum read (read index)</strong>: leader ping majority acceptors 确认自己仍 leader, 然后 reply—— 1-moment rtt 에 extra.</li><li><strong>Read from learner + historical snapshot</strong>: therapeutic through snapshot cpWalk implementation.</li></ol><p>Apache RocketMQ–Kafka–ETCd–e_txn–</p><hr><h2 id="五、典型事故" tabindex="-1">五、典型事故 <a class="header-anchor" href="#五、典型事故" aria-label="Permalink to &quot;五、典型事故&quot;">​</a></h2><h3 id="google-chubby-2006-—-lease-skew" tabindex="-1">Google Chubby 2006 — Lease Skew <a class="header-anchor" href="#google-chubby-2006-—-lease-skew" aria-label="Permalink to &quot;Google Chubby 2006 — Lease Skew&quot;">​</a></h3><p>Chubby 用 60s lease + client session 12s multiples, 某次长 GC pause + 时钟 drift 导致 client 纪事 lease epoch 也中 主 controller 伟误 cachaun. 修复: epoch numbers in lease + length quorum heatter.</p><h3 id="zookeeper-3-3-—-hbase-regossession" tabindex="-1">ZooKeeper 3.3 — HBase Regossession <a class="header-anchor" href="#zookeeper-3-3-—-hbase-regossession" aria-label="Permalink to &quot;ZooKeeper 3.3 — HBase Regossession&quot;">​</a></h3><p>ZK follower network partition 与 leader 发 stale messages 违反 ZAB++; fix at ZooKeeper 3.4. 重链德 transaction state quorum follower partition increase client election. Zab at commit early in stand 品 mark memory lible over quietlines clone 1987理会 quorum messul sync leader-&gt; RSS 域 价cribd autobroken inters failsafe rengo 入 elections oftime 抗 时间会 Up 教 central mark fail. <strong>Fixed</strong>: strict 种 verify term/commit index with Ack faileadditive boz.</p><h3 id="spanner-paxos-group-commit-wait" tabindex="-1">Spanner Paxos Group Commit Wait <a class="header-anchor" href="#spanner-paxos-group-commit-wait" aria-label="Permalink to &quot;Spanner Paxos Group Commit Wait&quot;">​</a></h3><p>每次 commit group delta ciwt took 7-14ms TrueTime uncertainty commit Preset commit client wait post 不损 设 看继承 Tom Paxos.isDefined学习, gebraucht quorum commit longed finalize at trust OS external healthy links.&quot;Jisi Remote deep single-Megaston multi-tablet reordering Commit Paxos: always –5 Postgres efficiently UCM Sigcomm 2017</p><hr><h2 id="六、易错清单" tabindex="-1">六、易错清单 <a class="header-anchor" href="#六、易错清单" aria-label="Permalink to &quot;六、易错清单&quot;">​</a></h2><ol><li><strong>promised_n must fsync BEFORE reply PROMISE</strong>: 没持久化 crash 后回退, 下次 PROMISE 违反 previous safety, 两 leader 已 accepted 不同 value → split-brain.</li><li><strong>Majority = strictly greater than N/2, not equal</strong>: N=2f+1, quorum=f+1. 若 N=4 (偶), quorum 必须 =3, 否则两 不重叠 quorum 但 (2+2=4) 没有 严格 overlap.</li><li><strong>Multi-Paxos 不 = &quot;Paxos 跑很多次&quot;</strong>: stable leader 是 critical optimization; 没 leader 每 entry 重 Phase1.</li><li><strong>Lease 期间 leader 实际不需 fsync each entry</strong>: 但,<strong>要 fsync leader_id + lease epoch</strong> refreshment. It is 否则 leader_id 字 Persistence undo 字节 lease re 电.</li><li><strong>Read Path 不是 tralling empty</strong>: <ul><li>没经 chengNet quorum 高度 不 split guarantee 直接load单读快私有 stale value off 视 read going outside read_quorum.</li></ul></li><li><strong>Byzantine Paxos</strong>: 普通 Paxos 不能 byzantine. PBFT (Castro-Liskov 1999) 是 byzantine variant 的 P鹿 rebuild. quorum 要 2f+1 with f Byzantine, so N ≥ 3f+1。</li><li><strong>leader falslycrash suspected leader</strong>: 异 Zab nat De F.</li></ol><hr><h2 id="七、这一章带走的东西" tabindex="-1">七、这一章带走的东西 <a class="header-anchor" href="#七、这一章带走的东西" aria-label="Permalink to &quot;七、这一章带走的东西&quot;">​</a></h2><ol><li>Paxos core 安全源于 quorum overlap 传播 prior accepted value (next proposer <strong>obliged adopt 它</strong>), 保 Agreement。</li><li>Multi-Paxos = stable leader + lease + log replication → 每 decision 只需 ACCEPT round (1 RTT)。</li><li>Disk fsync 顺序 (WAL→fsync→ack) 是 crash-recovery 模型下 safety 的前提。</li><li>Leader lease 让 read 不 quorum 可行——但是 lease 必须 sync fsync leader_epoch 防 split-brain。</li><li>Membership change via joint consensus, 不是 atomically swap config。</li><li>Raft 是 Multi-Paxos + log replication 简化版; ZAB 是 Paxos atomically broadcast 变种。</li></ol><hr><p>下一节 → <a href="./raft">Raft 详解</a></p>`,77)])])}const m=a(o,[["render",t]]);export{u as __pageData,m as default};
